import re
from dataclasses import dataclass, field
from typing import Optional

# "## [2.4.0] - 2024-05-02"
DATED_HEADING = re.compile(r"^## \[(?P<version>[^\]]+)\] - (?P<date>\d{4}-\d{2}-\d{2})\s*$")
# "## [Unreleased]" has no date.
UNRELEASED_HEADING = re.compile(r"^## \[(?P<version>Unreleased)\]\s*$")

# An HTML comment, single- or multi-line. The body cannot contain "-->", so each
# match ends at the first closing marker. A comment that ends its line also takes
# the whitespace before it and after it, so no trailing whitespace is left behind.
COMMENT = re.compile(
    r"[ \t]*<!--(?:(?!-->).)*-->[ \t]*(?=\n|\Z)|<!--(?:(?!-->).)*-->",
    re.DOTALL,
)


@dataclass
class Release:
    version: str
    date: Optional[str]
    body: list = field(default_factory=list)


def strip_comments(text):
    return COMMENT.sub("", text)


def _heading(line):
    match = DATED_HEADING.match(line)
    if match:
        return match.group("version"), match.group("date")
    match = UNRELEASED_HEADING.match(line)
    if match:
        return match.group("version"), None
    return None


def parse_changelog(text):
    # Comments go first so that nothing inside them is read as a heading or body line.
    text = strip_comments(text.replace("\r\n", "\n"))
    releases = []
    current = None
    for line in text.split("\n"):
        heading = _heading(line) if line.startswith("## ") else None
        if heading is not None:
            current = Release(*heading)
            releases.append(current)
        elif current is not None:
            current.body.append(line)
    return releases


def _tidy(lines):
    out = []
    for line in lines:
        if line.strip():
            out.append(line)
        elif out and out[-1] != "":
            out.append("")  # a run of blank lines becomes one blank line
    while out and out[0] == "":
        out.pop(0)
    while out and out[-1] == "":
        out.pop()
    return "\n".join(out)


def render_release(text, version):
    for release in parse_changelog(text):
        if release.version == version:
            if release.date:
                header = f"# {release.version} ({release.date})"
            else:
                header = f"# {release.version}"
            body = _tidy(release.body)
            if not body:
                return header + "\n"
            return f"{header}\n\n{body}\n"
    raise LookupError(version)

